+/**
+ * Removes characters that can break prompt structure or visually spoof content.
+ * - Unicode control chars (Cc)
+ * - Unicode format chars (Cf) incl. bidi / zero-width markers
+ * - Explicit line/paragraph separators (U+2028/U+2029)
+ */
+export function sanitizePromptText(value: string): string {
+  if (!value) return "";
+  return value.replace(/[\p{Cc}\p{Cf}\u2028\u2029]/gu, "");
+}
+
