@@ -0,0 +1,61 @@
+function splitRawCommand(rawCommand: string): string[] {
+  const argv: string[] = [];
+  let current = "";
+  let quote: '"' | "'" | null = null;
+  let escaped = false;
+
+  for (const ch of rawCommand) {
+    if (escaped) {
+      current += ch;
+      escaped = false;
+      continue;
+    }
+
+    if (ch === "\\" && quote !== "'") {
+      escaped = true;
+      continue;
+    }
+
+    if (quote) {
+      if (ch === quote) {
+        quote = null;
+      } else {
+        current += ch;
+      }
+      continue;
+    }
+
+    if (ch === '"' || ch === "'") {
+      quote = ch;
+      continue;
+    }
+
+    if (/\s/.test(ch)) {
+      if (current.length > 0) {
+        argv.push(current);
+        current = "";
+      }
+      continue;
+    }
+
+    current += ch;
+  }
+
+  if (escaped || quote) {
+    throw new Error("Invalid rawCommand");
+  }
+
+  if (current.length > 0) {
+    argv.push(current);
+  }
+
+  return argv;
+}
+
+export function rawCommandMatchesArgv(rawCommand?: string, command?: string[]): boolean {
+  if (!rawCommand || !Array.isArray(command) || command.length === 0) {
+    return true;
+  }
+
+  const parsed = splitRawCommand(rawCommand);
+  return parsed.length === command.length && parsed.every((v, i) => v === command[i]);
+}
+
