+
+function isDefaultPort(url: URL): boolean {
+  if (url.port) {
+    return false;
+  }
+  return true;
+}
+
+function getEffectivePort(url: URL): number {
+  if (url.port) {
+    return Number(url.port);
+  }
+  return url.protocol === 'wss:' ? 443 : 80;
+}
+
+function normalizeRootUrl(url: URL): string {
+  const port = isDefaultPort(url) ? '' : `:${url.port}`;
+  return `${url.protocol}//${url.hostname}${port}/`;
