+    return overrideUrl.toString();
+  }
+  if (LOOPBACK_HOSTS.has(overrideUrl.hostname) && getEffectivePort(overrideUrl) === configuredGatewayPort) {
+    return overrideUrl.toString();
+  }
+  throw new Error('Invalid gatewayUrl override: only configured remote URL or loopback gateway is allowed');
+}
